/**
 * Find production assets using the HTML generated by Vite.
 * Vite fingerprints asset filenames on each build (index-[hash].js/.css).
 * Tests must not depend on the names in a previously shipped dist/ folder.
 */
import assert from 'node:assert/strict';
import { readFileSync, existsSync } from 'node:fs';

const toFile = (assetPath) => {
  assert.match(assetPath, /^\/assets\/[a-zA-Z0-9._-]+\.(?:js|css)$/, `Unexpected Vite asset path: ${assetPath}`);
  return new URL(`../dist${assetPath}`, import.meta.url);
};

export function readProductionAssets() {
  const html = readFileSync(new URL('../dist/index.html', import.meta.url), 'utf8');
  const scriptPaths = [...html.matchAll(/<script\b[^>]*\bsrc=["']([^"']+\.js)["'][^>]*>/g)].map(match => match[1]);
  const stylePaths = [...html.matchAll(/<link\b[^>]*\bhref=["']([^"']+\.css)["'][^>]*>/g)].map(match => match[1]);
  assert.ok(scriptPaths.length > 0, 'Production HTML must reference at least one JavaScript bundle');
  assert.ok(stylePaths.length > 0, 'Production HTML must reference at least one CSS bundle');
  for (const assetPath of [...scriptPaths, ...stylePaths]) {
    assert.ok(existsSync(toFile(assetPath)), `Production asset missing: ${assetPath}`);
  }
  return {
    html,
    scriptPaths,
    stylePaths,
    js: scriptPaths.map(assetPath => readFileSync(toFile(assetPath), 'utf8')).join('\n'),
    css: stylePaths.map(assetPath => readFileSync(toFile(assetPath), 'utf8')).join('\n'),
  };
}
